// NEXAI Box-Wächter — wertet beide Prüfungen aus und meldet NUR Zustandswechsel.
// Läuft auf der Website-Box (5.75.179.247) und beobachtet die CRM-/Telefonie-Box
// (178.105.12.207) von außen. Genau die Lücke, die ein Wächter INNERHALB des CRM
// prinzipbedingt nicht abdecken kann: stirbt die Box, kann sie sich nicht selbst melden.
//
// Zustand liegt in den Workflow-Static-Data und überlebt damit die einzelnen Läufe
// (funktioniert nur, wenn der Workflow AKTIV ist — im Test-Modus wird nichts gespeichert).

const TARGETS = [
  { key: 'crm',      label: 'CRM-Box (crm.nex-a-i.com)', node: 'Check CRM',      url: 'https://crm.nex-a-i.com/' },
  { key: 'asterisk', label: 'Telefonie / Asterisk',      node: 'Check Asterisk', url: 'http://178.105.12.207:9101/asterisk' },
];
const FAILS_BEFORE_ALARM = 2;          // gegen kurze Aussetzer
const REMIND_MS = 60 * 60 * 1000;      // solange down: höchstens stündlich erinnern

const store = $getWorkflowStaticData('global');
const now = Date.now();
const stamp = (ms) => new Date(ms).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const dauer = (ms) => {
  const m = Math.round(ms / 60000);
  if (m < 60) return m + ' Minuten';
  const h = Math.floor(m / 60);
  return h + ' Std ' + (m % 60) + ' Min';
};
const out = [];

// Einmalige Bestätigung beim allerersten Lauf nach dem Aktivieren.
if (!store.__armed) {
  store.__armed = now;
  out.push({ json: {
    subject: 'Box-Wächter aktiv',
    text: 'Der externe Box-Wächter läuft ab jetzt auf der Website-Box und prüft alle 3 Minuten:\n\n'
        + TARGETS.map(t => '  • ' + t.label + '  →  ' + t.url).join('\n')
        + '\n\nDu bekommst eine Mail, sobald eines der beiden ausfällt — und wieder eine, sobald es zurück ist.\n'
        + 'Diese Nachricht kommt nur einmal, beim Scharfschalten.',
  } });
}

for (const t of TARGETS) {
  let code = 0;
  let detail = '';
  try {
    const j = $(t.node).first().json || {};
    code = Number(j.statusCode) || 0;
    if (typeof j.body === 'string') detail = j.body.slice(0, 300);
    else if (j.error) detail = String(j.error.message || j.error);
  } catch (e) {
    code = 0;
    detail = String((e && e.message) || e);
  }

  const ok = code >= 200 && code < 400;
  const s = store[t.key] || { down: false, fails: 0, since: 0, lastAlert: 0 };

  if (ok) {
    if (s.down) {
      out.push({ json: {
        subject: t.label + ' ist wieder erreichbar',
        text: t.url + '\n\nWieder erreichbar: ' + stamp(now)
            + '\nWar ausgefallen seit: ' + stamp(s.since) + ' (' + dauer(now - s.since) + ')',
      } });
    }
    store[t.key] = { down: false, fails: 0, since: now, lastAlert: 0 };
    continue;
  }

  const fails = (s.fails || 0) + 1;

  if (!s.down && fails >= FAILS_BEFORE_ALARM) {
    store[t.key] = { down: true, fails, since: now, lastAlert: now };
    out.push({ json: {
      subject: 'AUSFALL: ' + t.label + ' nicht erreichbar',
      text: t.url + '\n\nNicht erreichbar seit: ' + stamp(now)
          + '\nHTTP-Status: ' + (code || 'keine Antwort')
          + (detail ? '\nDetails: ' + detail : '')
          + '\n\n(nach ' + fails + ' Fehlversuchen in Folge — kurze Aussetzer lösen keinen Alarm aus)'
          + '\nDu bekommst eine weitere Mail, sobald es wieder läuft.',
    } });
  } else if (s.down && now - (s.lastAlert || 0) >= REMIND_MS) {
    store[t.key] = { down: true, fails, since: s.since, lastAlert: now };
    out.push({ json: {
      subject: 'AUSFALL hält an: ' + t.label,
      text: t.url + '\n\nWeiterhin nicht erreichbar (HTTP ' + (code || 'keine Antwort') + ').'
          + '\nAusgefallen seit: ' + stamp(s.since) + ' (' + dauer(now - s.since) + ')',
    } });
  } else {
    store[t.key] = { down: s.down, fails, since: s.since || now, lastAlert: s.lastAlert || 0 };
  }
}

// Keine Items = nichts zu melden. Der Gmail-Node läuft dann gar nicht erst.
return out;
